1	<!DOCTYPE html>
2	<html lang="id">
3	<head>
4	<meta charset="UTF-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1.0">
6	<title>AkunPro — Sistem Akuntansi F&B</title>
7	<link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/@tabler/icons-webfont@3.10.0/dist/tabler-icons.min.css">
8	<style>
9	*{box-sizing:border-box;margin:0;padding:0}
10	:root{--or:#e8611a;--orl:#fef0e8;--orm:#f7a86e;--s2:#fff;--s1:#f7f7f5;--s0:#f0efec;--bd:rgba(11,11,11,0.10);--tp:#0b0b0b;--ts:#52514e;--tm:#898781;--rad:8px;--gr:#0a7a3e;--grl:#e6f9ee;--rd:#c0392b;--rdl:#fdecea;--bl:#1a5fc8;--bll:#e8f2fe;--yl:#a07800;--yll:#fef9e0}
11	body{font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;font-size:13px;background:var(--s0);color:var(--tp);overflow:hidden}
12	.app{display:flex;height:100vh}
13	.sb{width:215px;min-width:215px;background:var(--s2);border-right:0.5px solid var(--bd);display:flex;flex-direction:column;overflow-y:auto}
14	.sb-brand{padding:14px 12px 12px;border-bottom:0.5px solid var(--bd)}
15	.brow{display:flex;align-items:center;gap:9px}
16	.bico{width:33px;height:33px;background:var(--or);border-radius:8px;display:flex;align-items:center;justify-content:center;flex-shrink:0}
17	.bico i{color:#fff;font-size:18px}
18	.bname{font-size:13px;font-weight:700;color:var(--tp)}
19	.bsub2{font-size:10px;color:var(--tm)}
20	.nsec{padding:8px 7px 2px}
21	.nlbl{font-size:9px;font-weight:700;color:var(--tm);letter-spacing:.08em;text-transform:uppercase;padding:0 6px;margin-bottom:3px}
22	.ni{display:flex;align-items:center;gap:8px;padding:6px 8px;border-radius:var(--rad);cursor:pointer;font-size:12px;color:var(--ts);margin-bottom:1px;transition:background .12s;user-select:none}
23	.ni:hover{background:var(--s1)}
24	.ni.act{background:var(--orl);color:var(--or);font-weight:600}
25	.ni.act i{color:var(--or)}
26	.ni i{font-size:15px;color:var(--tm);flex-shrink:0}
27	.sb-foot{margin-top:auto;padding:10px 7px;border-top:0.5px solid var(--bd)}
28	.pbox{background:var(--s1);border:0.5px solid var(--bd);border-radius:var(--rad);padding:8px 10px;cursor:pointer}
29	.pbox:hover{background:var(--s0)}
30	.plbl{font-size:9px;color:var(--tm);margin-bottom:2px;font-weight:600;text-transform:uppercase;letter-spacing:.04em}
31	.pval{font-size:12px;font-weight:600;color:var(--tp);display:flex;justify-content:space-between;align-items:center}
32	.main{flex:1;display:flex;flex-direction:column;overflow:hidden;min-width:0}
33	.topbar{display:flex;align-items:center;justify-content:space-between;padding:9px 18px;border-bottom:0.5px solid var(--bd);background:var(--s2);flex-shrink:0}
34	.bc{font-size:12px;color:var(--tm)}.bc b{color:var(--tp)}
35	.tr2{display:flex;align-items:center;gap:8px}
36	.live{background:var(--grl);color:var(--gr);font-size:10px;font-weight:600;padding:2px 8px;border-radius:20px}
37	.asv{display:inline-flex;align-items:center;gap:3px;font-size:10px;color:var(--gr);font-weight:600;background:var(--grl);padding:2px 7px;border-radius:20px}
38	.content{flex:1;overflow-y:auto;padding:16px 18px}
39	.pg{display:none}.pg.act{display:block}
40	.pt{font-size:17px;font-weight:700;color:var(--tp);margin-bottom:2px}
41	.ps{font-size:12px;color:var(--tm);margin-bottom:12px}
42	.g4{display:grid;grid-template-columns:repeat(4,1fr);gap:9px;margin-bottom:10px}
43	.g3{display:grid;grid-template-columns:repeat(3,1fr);gap:9px;margin-bottom:10px}
44	.g2{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:10px}
45	.card{background:var(--s2);border:0.5px solid var(--bd);border-radius:12px;padding:13px 15px;margin-bottom:10px}
46	.sc{background:var(--s2);border:0.5px solid var(--bd);border-radius:12px;padding:11px 13px}
47	.sico{width:27px;height:27px;border-radius:7px;display:flex;align-items:center;justify-content:center;margin-bottom:7px;font-size:13px}
48	.slbl{font-size:9px;color:var(--tm);text-transform:uppercase;letter-spacing:.05em;margin-bottom:2px;font-weight:600}
49	.sval{font-size:15px;font-weight:700;color:var(--tp);margin-bottom:1px}
50	.ssub{font-size:10px;color:var(--ts)}
51	.tw{overflow-x:auto}
52	.tbl{width:100%;border-collapse:collapse;font-size:12px}
53	.tbl th{color:var(--tm);font-weight:600;text-align:left;padding:5px 8px;border-bottom:0.5px solid var(--bd);font-size:11px;white-space:nowrap;background:var(--s1)}
54	.tbl td{padding:6px 8px;border-bottom:0.5px solid var(--bd);color:var(--tp);vertical-align:middle}
55	.tbl tr:last-child td{border-bottom:none}
56	.tbl tbody tr:hover td{background:var(--s1)}
57	.pill{display:inline-block;padding:2px 7px;border-radius:20px;font-size:10px;font-weight:600}
58	.pg2{background:var(--grl);color:var(--gr)}.py{background:var(--yll);color:var(--yl)}.pr{background:var(--rdl);color:var(--rd)}.pb{background:var(--bll);color:var(--bl)}.por{background:var(--orl);color:var(--or)}
59	.btn{display:inline-flex;align-items:center;gap:5px;padding:5px 11px;border-radius:var(--rad);border:0.5px solid var(--bd);background:var(--s1);color:var(--tp);font-size:12px;cursor:pointer;font-family:inherit;transition:all .12s;font-weight:500}
60	.btn:hover{background:var(--s0)}
61	.bor{background:var(--or);color:#fff;border-color:var(--or)}.bor:hover{background:#d4561a}
62	.bgr{background:var(--gr);color:#fff;border-color:var(--gr)}.bgr:hover{background:#086030}
63	.brd{background:var(--rd);color:#fff;border-color:var(--rd)}
64	.bsm{padding:3px 8px;font-size:11px}
65	.brow3{display:flex;gap:7px;margin-bottom:10px;flex-wrap:wrap;align-items:center}
66	.hrow{display:flex;justify-content:space-between;align-items:center;margin-bottom:9px}
67	.htitle{font-size:13px;font-weight:700;color:var(--tp)}
68	.fg{display:flex;flex-direction:column;gap:3px;margin-bottom:8px}
69	.fg label{font-size:11px;color:var(--tm);font-weight:600}
70	.fg input,.fg select,.fg textarea{padding:6px 9px;border:0.5px solid var(--bd);border-radius:var(--rad);font-size:12px;font-family:inherit;background:var(--s2);color:var(--tp);outline:none;transition:border-color .12s;width:100%}
71	.fg input:focus,.fg select:focus{border-color:var(--or);box-shadow:0 0 0 2px rgba(232,97,26,.1)}
72	.fgrid{display:grid;grid-template-columns:1fr 1fr;gap:8px}
73	.fgrid3{display:grid;grid-template-columns:1fr 1fr 1fr;gap:8px}
74	.tabs{display:flex;gap:2px;margin-bottom:10px;background:var(--s1);padding:3px;border-radius:var(--rad);width:fit-content;border:0.5px solid var(--bd)}
