  unpaid: "Belum Bayar",
  active: "Aktif",
  past_due: "Jatuh Tempo",
  expired: "Kedaluwarsa",
};

function formatDate(dateStr: string) {
  return new Date(dateStr).toLocaleDateString("id-ID", {
    day: "2-digit",
    month: "short",
    year: "numeric",
  });
}

export default async function AdminPage() {
