      <p className="mb-1 text-[10.5px] font-semibold uppercase tracking-wide text-zinc-400">
        {label}
      </p>
      <p className={`text-xl font-bold ${VALUE_TONE[tone]}`}>{value}</p>
      {sub && <p className="mt-0.5 text-[10.5px] text-zinc-400">{sub}</p>}
    </div>
  );
}

