14	
15	type SupabaseServerClient = Awaited<ReturnType<typeof createClient>>;
16	type AccountRow = { id: string; code: string; type: string; normal_balance: string };
17	
18	function formatRupiah(value: number) {
19	  const sign = value < 0 ? "-" : "";
20	  return `${sign}Rp${Math.round(Math.abs(value)).toLocaleString("id-ID")}`;
21	}
22	
23	// Total Modal (Modal Pemilik + Laba Ditahan + Laba Berjalan) as of a point in
24	// time — same 3-part sum Neraca uses, evaluated at an arbitrary cutoff so it
25	// can be diffed across a period. `strictlyBeforeIso: null` means "since the
26	// business's inception" (i.e. balance 0, there's nothing before that).
27	async function totalModalAsOf(
28	  supabase: SupabaseServerClient,
29	  businessId: string,
30	  accounts: AccountRow[],
31	  strictlyBeforeIso: string | null,
32	): Promise<number> {
33	  if (strictlyBeforeIso === null) return 0;
34	
35	  const { data: entries } = await supabase
36	    .from("journal_entries")
37	    .select("journal_lines(debit, credit, account_id)")
38	    .eq("business_id", businessId)
39	    .lt("date", strictlyBeforeIso);
40	
41	  const balanceByAccount = new Map<string, number>();
42	  for (const entry of entries ?? []) {
43	    const lines = entry.journal_lines as unknown as {
44	      debit: number;
45	      credit: number;
46	      account_id: string;
47	    }[];
48	    for (const l of lines) {
49	      const cur = balanceByAccount.get(l.account_id) ?? 0;
50	      balanceByAccount.set(l.account_id, cur + Number(l.debit) - Number(l.credit));
51	    }
52	  }
53	
54	  let modalTotal = 0;
55	  let pendapatanTotal = 0;
56	  let bebanTotal = 0;
57	  for (const a of accounts) {
58	    const raw = balanceByAccount.get(a.id) ?? 0;
59	    const balance = a.normal_balance === "debit" ? raw : -raw;
60	    if (a.type === "modal") modalTotal += balance;
61	    else if (a.type === "pendapatan") pendapatanTotal += balance;
62	    else if (a.type === "beban") bebanTotal += balance;
63	  }
64	  return modalTotal + pendapatanTotal - bebanTotal;
65	}
66	
67	export default async function LaporanPerubahanModalPage({
68	  params,
69	  searchParams,
70	}: {
71	  params: Promise<{ businessId: string }>;
72	  searchParams: Promise<{ period?: string; from?: string; to?: string }>;
73	}) {
74	  const { businessId } = await params;
75	  const { period: periodParam, from, to } = await searchParams;
76	  const cookieStore = await cookies();
77	  const period = parsePeriod(periodParam ?? cookieStore.get(PERIOD_COOKIE_NAME)?.value);
78	  const { fromIso, toIsoExclusive } = getPeriodRange(period, from, to);
79	
80	  const supabase = await createClient();
81	
82	  const { data: business } = await supabase
83	    .from("businesses")
84	    .select("id, name")
85	    .eq("id", businessId)
86	    .single();
87	
88	  if (!business) {
89	    notFound();
90	  }
91	
92	  const { data: accounts } = await supabase
93	    .from("accounts")
94	    .select("id, code, type, normal_balance")
95	    .eq("business_id", businessId)
96	    .in("type", ["modal", "pendapatan", "beban"]);
97	
98	  const accountRows = (accounts ?? []) as AccountRow[];
99	  const modalPemilikAccount = accountRows.find((a) => a.code === "3-001");
100	
101	  // "Now" as an upper cutoff for open-ended periods (today/week/month/all).
102	  const nowIso = new Date().toISOString();
103	  const modalAkhirCutoff = toIsoExclusive ?? nowIso;
104	
105	  const [modalAwal, modalAkhir] = await Promise.all([
106	    totalModalAsOf(supabase, businessId, accountRows, fromIso),
107	    totalModalAsOf(supabase, businessId, accountRows, modalAkhirCutoff),
108	  ]);
109	
110	  let setoran = 0;
111	  let prive = 0;
112	  if (modalPemilikAccount) {
113	    let periodQuery = supabase
114	      .from("journal_entries")
115	      .select("journal_lines(debit, credit, account_id)")
116	      .eq("business_id", businessId);
117	    if (fromIso) periodQuery = periodQuery.gte("date", fromIso);
118	    if (toIsoExclusive) periodQuery = periodQuery.lt("date", toIsoExclusive);
119	    const { data: periodEntries } = await periodQuery;
120	
121	    for (const entry of periodEntries ?? []) {
122	      const lines = entry.journal_lines as unknown as {
123	        debit: number;
124	        credit: number;
125	        account_id: string;
126	      }[];
127	      for (const l of lines) {
128	        if (l.account_id !== modalPemilikAccount.id) continue;
129	        setoran += Number(l.credit);
130	        prive += Number(l.debit);
131	      }
132	    }
133	  }
134	
135	  const labaBersihPeriode = modalAkhir - modalAwal - (setoran - prive);
136	
137	  const boundAddCapital = addCapitalMovement.bind(null, businessId);
138	  const today = new Date().toLocaleDateString("en-CA", { timeZone: "Asia/Jakarta" });
139	
140	  return (
141	    <div className="w-full max-w-2xl">
142	      <div className="flex flex-wrap items-center justify-between gap-2">
143	        <div>
144	          <h1 className="text-lg font-bold text-zinc-900">Perubahan Modal — {business.name}</h1>
145	          <p className="mt-0.5 text-xs text-zinc-500">{PERIOD_DESCRIPTIONS[period]}</p>
146	        </div>
147	        <PeriodTabs basePath={`/business/${businessId}/accounting/modal`} period={period} />
148	      </div>
149	
150	      {period === "custom" && (
151	        <form
152	          method="get"
153	          className="mt-4 flex flex-wrap items-end gap-3 rounded-2xl border border-zinc-200 bg-white p-4"
154	        >
155	          <input type="hidden" name="period" value="custom" />
156	          <label className="text-xs font-medium text-zinc-600">
157	            Dari
158	            <input
159	              type="date"
160	              name="from"
161	              defaultValue={from}
162	              className="mt-1 block rounded-lg border border-zinc-200 px-2 py-1.5 text-sm"
163	            />
164	          </label>
165	          <label className="text-xs font-medium text-zinc-600">
166	            Sampai
167	            <input
