const fs = require("fs");
const path = require("path");
const { Client } = require("pg");

const MIGRATIONS_DIR = path.join(__dirname, "..", "..", "..", "..", "..", "..", "..", "PROJECT1", "KasirKu", "supabase", "migrations");

async function main() {
  const connectionString = process.env.DEV_DB_URL;
  if (!connectionString) {
    console.error("Set DEV_DB_URL env var first.");
    process.exit(1);
  }

  const dir = "G:/PROJECT1/KasirKu/supabase/migrations";
  const files = fs.readdirSync(dir).filter((f) => f.endsWith(".sql")).sort();
  console.log(`Found ${files.length} migration files.`);

  const client = new Client({ connectionString, ssl: { rejectUnauthorized: false } });
  await client.connect();
  console.log("Connected to dev database.");

  for (const file of files) {
    const sql = fs.readFileSync(path.join(dir, file), "utf8");
    process.stdout.write(`Applying ${file} ... `);
    try {
      await client.query(sql);
      console.log("OK");
    } catch (err) {
      console.log("FAILED");
      console.error(err.message);
      await client.end();
      process.exit(1);
    }
  }

  await client.end();
  console.log("All migrations applied successfully.");
}

main();

