218	<script>
219	(function(){
220	  var root = document.documentElement;
221	  function applyTheme(){}
222	  var items = [
223	    {n:"Kopi Susu x2", p:36000},
224	    {n:"Roti Bakar x1", p:18500},
225	    {n:"Es Teh Manis x3", p:15000}
226	  ];
227	  function rupiah(v){ return "Rp" + Math.round(v).toLocaleString("id-ID"); }
228	  var reduce = window.matchMedia && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
229	  var itemsEl = document.getElementById("r-items");
230	  var subEl = document.getElementById("r-sub");
231	  var taxEl = document.getElementById("r-tax");
232	  var totalEl = document.getElementById("r-total");
233	  var stampEl = document.getElementById("r-stamp");
234	
235	  function render(count){
236	    itemsEl.innerHTML = "";
237	    var sub = 0;
238	    for(var i=0;i<count;i++){
239	      var it = items[i];
240	      sub += it.p;
241	      var row = document.createElement("div");
242	      row.style.display = "flex";
243	      row.style.justifyContent = "space-between";
244	      row.style.margin = "0 0 5px";
245	      row.innerHTML = "<span>"+it.n+"</span><span>"+rupiah(it.p)+"</span>";
246	      itemsEl.appendChild(row);
247	    }
248	    var tax = sub * 0.1;
249	    subEl.textContent = rupiah(sub);
250	    taxEl.textContent = rupiah(tax);
251	    totalEl.textContent = rupiah(sub + tax);
252	    if(count >= items.length){
253	      stampEl.style.opacity = "1";
254	      stampEl.style.transform = "rotate(-8deg) scale(1)";
255	    } else {
256	      stampEl.style.opacity = "0";
257	      stampEl.style.transform = "rotate(-8deg) scale(.85)";
258	    }
259	  }
260	
261	  if(reduce){
262	    render(items.length);
263	  } else {
264	    var step = 0;
265	    render(0);
266	    setInterval(function(){
267	      step = (step + 1) % (items.length + 2);
268	      render(Math.min(step, items.length));
269	    }, 900);
270	  }
271	
272	  var features = [
273	    ["Kasir & Struk Instan","Transaksi cepat, cetak atau kirim struk, dukung banyak metode pembayaran.","POS"],
274	    ["Stok & Resep Otomatis","Stok bahan baku berkurang otomatis sesuai resep setiap ada transaksi.","INVENTORY"],
275	    ["Self-Order via QR","Pelanggan pesan langsung dari meja lewat scan QR, masuk ke antrian kasir.","QR"],
276	    ["Laporan Real-Time","Penjualan, laba rugi, dan arus kas selalu ter-update tanpa hitung manual.","REPORTS"],
277	    ["Kelola Kasir & Shift","PIN kasir per orang, buka/tutup shift, rekonsiliasi kas otomatis.","SHIFT"],
278	    ["Payroll & Absensi","Gaji harian, absensi, dan slip gaji karyawan dalam satu tempat.","HR"],
279	    ["Data Pelanggan & Member","Riwayat pembelian, kartu member, dan harga khusus pelanggan tetap.","CRM"],
280	    ["Aman & Multi-Toko","Setiap toko terisolasi datanya, kelola beberapa cabang dari satu akun.","SECURITY"]
281	  ];
282	  var list = document.getElementById("feature-list");
283	  features.forEach(function(f){
284	    var row = document.createElement("div");
285	    row.className = "feat-row";
286	    row.innerHTML = '<div><p class="fname">'+f[0]+'</p><p class="fdesc">'+f[1]+'</p></div><span class="ftag">'+f[2]+'</span>';
287	    list.appendChild(row);
288	  });
289	})();
290	</script>
