@import "tailwindcss";

:root {
  --background: #ffffff;
  --foreground: #171717;
}

@theme inline {
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --font-sans: var(--font-geist-sans);
  --font-mono: var(--font-geist-mono);

  /* Brand palette — Majoo-style bright green (primary ~#00A651). */
  --color-brand-50: #e6f9f0;
  --color-brand-100: #c3f0dc;
  --color-brand-200: #8fe0be;
  --color-brand-300: #57ce9c;
  --color-brand-400: #22b87a;
  --color-brand-500: #00a651;
  --color-brand-600: #00944a;
  --color-brand-700: #007a3d;
  --color-brand-800: #005c2e;
  --color-brand-900: #003d1f;
}

@media (prefers-color-scheme: dark) {
  :root {
    --background: #0a0a0a;
    --foreground: #ededed;
  }
}

body {
  background: var(--background);
  color: var(--foreground);
  font-family: Arial, Helvetica, sans-serif;
}

